payload.message:
Do it in TS, not template. Angular template `@switch` can branch, but TypeScript cannot exhaustively check it well there.

Use a small helper:

```ts
private getUnitNavContext(): NavControlContext | null {
  switch (this.tcs.booklet?.config.navbar_unit_label) {
  case 'HIDDEN':
    return null;

  case 'INDEX':
    return {
      labelMode: 'INDEX',
      readonly: this.tcs.booklet?.config.navbar_unit_controls_hidden === 'TRUE',
      label: 'Aufgabe',
      currentIndex: this.tcs.currentUnitSequenceId - 1,
      maxIndex: Object.keys(this.tcs.units).length
    };

  case 'LABEL':
    return {
      labelMode: 'LABEL',
      readonly: this.tcs.booklet?.config.navbar_unit_controls_hidden === 'TRUE',
      label: this.currentUnit?.label || '',
      currentIndex: this.tcs.currentUnitSequenceId - 1,
      maxIndex: Object.keys(this.tcs.units).length
    };

  default:
    return this.assertNever(this.tcs.booklet?.config.navbar_unit_label);
  }
}

private assertNever(value: never): never {
  throw new Error(`Unhandled navbar_unit_label: ${value}`);
}
```

Then template becomes simple:

```html
@if (unitNavContext && testLoaded) {
  <tc-navigation-control [navContext]="unitNavContext"
                         dataCy="unit-navigation"
                         (back)="tcs.setUnitNavigationRequest(unitNavigationTarget.PREVIOUS)"
                         (forward)="tcs.setUnitNavigationRequest(unitNavigationTarget.NEXT)">
  </tc-navigation-control>
}
```

But current `unitNavContext` type is not nullable. So change:

```ts
unitNavContext: NavControlContext | null = null;
```

Then places reading it need `?.` or guards, e.g.:

```html
[disabled]="!unitNavContext?.isBackwardAllowed && !pageNavContext.isBackwardAllowed"
```

If you only want exhaustive check for label mode, keep visibility in template and switch only the context creation. `HIDDEN` then should still be handled in the switch, otherwise no exhaustiveness.

